package Time3Hot100;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;

public class Solution_17_Hot100 {

    HashMap<Integer, List<Character>> phone = new HashMap<>();
    List<Character> list2 = new ArrayList<>();
    List<Character> list3 = new ArrayList<>();
    List<Character> list4 = new ArrayList<>();
    List<Character> list5 = new ArrayList<>();
    List<Character> list6 = new ArrayList<>();
    List<Character> list7 = new ArrayList<>();
    List<Character> list8 = new ArrayList<>();
    List<Character> list9 = new ArrayList<>();
    List<String> globalans = new ArrayList<>();
    StringBuilder curlevel = new StringBuilder();



    public void backTracing(String digits){
        if (curlevel.length() == digits.length()){
            globalans.add(curlevel.toString());
        }

        Integer curidx = curlevel.length()+1;
        List<Character> characters = phone.get(curidx);
        for (Character character : characters) {
            curlevel.append(character);
            backTracing(digits);
            curlevel.deleteCharAt(curlevel.length()-1);
        }
    }

    public List<String> letterCombinations(String digits) {


        phone.put(2, list2);
        phone.put(3, list3);
        phone.put(4, list4);
        phone.put(5, list5);
        phone.put(6, list6);
        phone.put(7, list7);
        phone.put(8, list8);
        phone.put(9, list9);

        backTracing(digits);
        return globalans;
    }

    public static void main(String[] args) {
        Solution_17_Hot100 solution17Hot100 = new Solution_17_Hot100();
        List<String> strings = solution17Hot100.letterCombinations("23");
        System.out.println(strings);
    }

}

